required <- c("shiny","bslib","dplyr","tidyr","readr","ggplot2","plotly","DT","shinyjs")
missing <- required[!vapply(required,requireNamespace,logical(1),quietly=TRUE)]
if(length(missing)) stop("Missing R packages: ",paste(missing,collapse=", "),". Run .\\setup.ps1 and restart the app.")
source("global.R")
library(shiny); library(bslib); library(plotly); library(DT)

theme <- bs_theme(version=5,bg="#0b1220",fg="#e7edf5",primary="#46e6a5",secondary="#52c7e8",base_font=font_google("Manrope"),heading_font=font_google("Space Grotesk"))
navs <- c("Overview","Player Intelligence","Team Intelligence","Venue Intelligence","Head-to-Head Analysis","Predictive Analytics","Data Explorer","Ask CricLens")
fmt <- function(x) if(length(x)&&is.finite(x)) format(round(x),big.mark=",") else "—"
card <- function(label,value,sub="") div(class="metric",div(class="metric-label",label),div(class="metric-value",value),div(class="metric-sub",sub))
empty_panel <- function() div(class="empty",h3("Add an IPL dataset to begin"),p("Place a ball-by-ball CSV in data/raw. CricLens will validate, normalize and process it on startup."),p("Expected fields include match ID, innings, batting team, batter, bowler, runs and over. See data/README.md for supported aliases."))
chart <- function(d,x,y,title,type="bar",color="#46e6a5") {
  if(is.null(d)||!nrow(d)) return(plotlyOutput("_empty",height="1px"))
  p<-plotly::plot_ly(d,x=~.data[[x]],y=~.data[[y]],type=type,mode=if(type=="scatter") "lines+markers" else NULL,
    marker=list(color=color),text=~paste0(.data[[x]],"<br>",.data[[y]]),hoverinfo="text")
  plotly::layout(p,title=list(text=title),paper_bgcolor="transparent",plot_bgcolor="transparent",font=list(color="#cbd5e1"),xaxis=list(title=""),yaxis=list(title=""),margin=list(t=48,b=45))
}
page_head <- function(kicker,title,desc) div(class="page-head",div(class="kicker",kicker),h1(title),p(desc))
filter_choices <- if(is.null(criclens_data$data)) list(seasons=numeric(),teams=character(),venues=character()) else list(
  seasons=sort(unique(stats::na.omit(criclens_data$data$season))),
  teams=sort(unique(stats::na.omit(c(criclens_data$data$team,criclens_data$data$opposition)))),
  venues=sort(unique(stats::na.omit(criclens_data$data$venue))))

ui <- navbarPage(title=div(class="brand",span("C",class="brand-mark"),span("CRICLENS")),id="nav",theme=theme,
  header=tagList(tags$head(tags$link(rel="stylesheet",type="text/css",href="style.css")),div(class="topline",span("IPL INTELLIGENCE SYSTEM"),span(if(is.null(criclens_data$data)) "DATASET NEEDED" else paste("DATA READY ·",criclens_data$message))),if(is.null(criclens_data$data))NULL else div(class="global-filters",selectInput("season","Season",choices=c("All seasons",filter_choices$seasons),selected="All seasons"),selectInput("team","Team",choices=c("All teams",filter_choices$teams),selected="All teams"),selectInput("venue","Venue",choices=c("All venues",filter_choices$venues),selected="All venues"))),
  tabPanel("Overview",value=navs[1],uiOutput("overview")),
  tabPanel("Player Intelligence",value=navs[2],uiOutput("players")),
  tabPanel("Team Intelligence",value=navs[3],uiOutput("teams")),
  tabPanel("Venue Intelligence",value=navs[4],uiOutput("venues")),
  tabPanel("Head-to-Head Analysis",value=navs[5],uiOutput("h2h")),
  tabPanel("Predictive Analytics",value=navs[6],uiOutput("predictions")),
  tabPanel("Data Explorer",value=navs[7],uiOutput("explorer")),
  tabPanel("Ask CricLens",value=navs[8],uiOutput("ask")))

server <- function(input,output,session) {
  d <- criclens_data$data
  output$overview <- renderUI({ if(is.null(d)) return(empty_panel()); seasons<-sort(unique(d$season[!is.na(d$season)])); teams<-sort(unique(c(d$team,d$opposition))); venues<-sort(unique(d$venue[!is.na(d$venue)]));
    tagList(page_head("MATCH INTELLIGENCE / 01","From every ball to every insight.",paste("Verified coverage",min(seasons),"—",max(seasons),"· Filter the complete delivery record.")),
      uiOutput("kpis"),div(class="grid two",div(class="panel",plotlyOutput("season_chart",height="300px")),div(class="panel",plotlyOutput("team_chart",height="300px"))),
      div(class="grid two",div(class="panel",h3("Run leaders"),DTOutput("top_runs")),div(class="panel",h3("Wicket leaders"),DTOutput("top_wickets")),div(class="panel",h3("Venue scoring profile"),DTOutput("venue_table")))) })
  filtered <- reactive({ if(is.null(d)) return(NULL); s<-input$season; filter_deliveries(d,if(is.null(s)||s=="All seasons") NULL else as.numeric(s),if(is.null(input$team)||input$team=="All teams") NULL else input$team,if(is.null(input$venue)||input$venue=="All venues") NULL else input$venue) })
  overview_stats <- reactive({
    x<-filtered(); if(is.null(x)) return(NULL)
    list(batting=player_batting(x),bowling=player_bowling(x),teams=team_records(x),venues=venue_summary(x))
  })
  output$kpis<-renderUI({x<-filtered(); if(is.null(x))return(NULL); s<-unique(x$season[!is.na(x$season)]); tagList(div(class="kpis",card("SEASONS",length(s)),card("MATCHES",fmt(length(unique(x$match_id)))),card("DELIVERIES",fmt(nrow(x))),card("PLAYERS",fmt(length(unique(x$player[!is.na(x$player)])))),card("TEAMS",length(unique(c(x$team,x$opposition)))),card("VENUES",length(unique(x$venue[!is.na(x$venue)])))) )})
  output$season_chart<-renderPlotly({x<-filtered(); a<-season_summary(x); if(!nrow(a))return(NULL); g<-ggplot2::ggplot(a,ggplot2::aes(x=season,y=matches))+ggplot2::geom_col(fill="#46e6a5",width=.72)+ggplot2::labs(title="Matches by season",x=NULL,y="Matches")+ggplot2::theme_minimal(base_size=12)+ggplot2::theme(plot.background=ggplot2::element_rect(fill="transparent",colour=NA),panel.background=ggplot2::element_rect(fill="transparent",colour=NA),text=ggplot2::element_text(colour="#cbd5e1"),panel.grid.minor=ggplot2::element_blank()); plotly::ggplotly(g,tooltip=c("x","y"))})
  output$team_chart<-renderPlotly({a<-overview_stats()$teams; if(!nrow(a))return(NULL); a<-a[order(-a$win_pct),]; plotly::plot_ly(a,x=~reorder(team,win_pct),y=~win_pct,type="bar",marker=list(color="#52c7e8")) |> plotly::layout(title="Team win rate · decided games",paper_bgcolor="transparent",plot_bgcolor="transparent",font=list(color="#cbd5e1"),xaxis=list(title="",tickangle=-40),yaxis=list(title="Win %"),margin=list(t=55,b=105,l=55,r=20))})
  output$top_runs<-renderDT({a<-overview_stats()$batting; datatable(head(a[order(-a$runs),],10),options=list(dom="tip",pageLength=10),rownames=FALSE)})
  output$top_wickets<-renderDT({a<-overview_stats()$bowling; datatable(head(a[order(-a$wickets),],10),options=list(dom="tip",pageLength=10),rownames=FALSE)})
  output$venue_table<-renderDT({a<-overview_stats()$venues; datatable(head(a[order(-a$matches),],12),options=list(dom="tip",pageLength=12),rownames=FALSE)})

  output$players<-renderUI({if(is.null(d))return(empty_panel()); tagList(page_head("PLAYER INTELLIGENCE / 02","Player profiles","Batting and bowling output, opportunity-adjusted context and phase performance."),div(class="filters",selectInput("player","Player",choices=sort(unique(na.omit(d$player)))),selectInput("player_season","Season",choices=c("All seasons",sort(unique(d$season)))),selectInput("player_opposition","Opposition",choices=c("All teams",sort(unique(na.omit(d$opposition))))),selectInput("player_venue","Venue",choices=c("All venues",sort(unique(na.omit(d$venue))))),sliderInput("bat_weight","Impact score batting weight",min=0,max=1,value=.6,step=.1),sliderInput("bowl_weight","Impact score bowling weight",min=0,max=1,value=.4,step=.1)),uiOutput("player_kpis"),div(class="grid two",div(class="panel",plotlyOutput("player_seasons",height="300px")),div(class="panel",plotlyOutput("player_phases",height="300px"))),div(class="grid two",div(class="panel",h3("Bowling profile"),DTOutput("player_bowling")),div(class="panel",h3("Custom impact score"),p("Batting average plus independent strike-rate efficiency, blended with bowling economy and wicket-rate residuals; opportunity-shrunk. Boundary share is excluded to limit overlap. This is not an official statistic."),textOutput("impact_weights"),uiOutput("impact_note"),DTOutput("impact_table"))),div(class="panel",h3("Match-by-match batting"),DTOutput("player_matches")))})
  px<-reactive({if(is.null(d))return(NULL); x<-filtered(); x<-x[x$player==input$player,,drop=FALSE]; if(!is.null(input$player_season)&&input$player_season!="All seasons") x<-x[x$season==as.numeric(input$player_season),,drop=FALSE]; if(!is.null(input$player_opposition)&&input$player_opposition!="All teams") x<-x[x$opposition==input$player_opposition,,drop=FALSE]; if(!is.null(input$player_venue)&&input$player_venue!="All venues") x<-x[x$venue==input$player_venue,,drop=FALSE]; x})
  player_bowling_rows<-reactive({x<-filtered(); if(is.null(x))return(NULL); x<-x[x$bowler==input$player,,drop=FALSE]; if(!is.null(input$player_season)&&input$player_season!="All seasons")x<-x[x$season==as.numeric(input$player_season),,drop=FALSE]; if(!is.null(input$player_opposition)&&input$player_opposition!="All teams")x<-x[x$team==input$player_opposition,,drop=FALSE]; if(!is.null(input$player_venue)&&input$player_venue!="All venues")x<-x[x$venue==input$player_venue,,drop=FALSE]; x})
  output$player_kpis<-renderUI({x<-px(); if(is.null(x)||!nrow(x))return(div(class="empty","No batting records for this selection.")); a<-player_batting(x); bx<-player_bowling_rows(); b<-player_bowling(bx); r<-if(nrow(a))a[1,] else NULL; pm<-player_match_batting(x,input$player); variability<-if(nrow(pm)>1)sd(pm$runs,na.rm=TRUE) else NA_real_; tagList(div(class="kpis",card("RUNS",if(is.null(r))"—" else fmt(r$runs)),card("BATTING AVG",if(is.null(r))"—" else round(r$average,1)),card("STRIKE RATE",if(is.null(r))"—" else round(r$strike_rate,1)),card("WICKETS",if(nrow(b))fmt(sum(b$wickets)) else "—"),card("BOUNDARY SHARE",if(is.null(r))"—" else paste0(round(r$boundary_pct,1),"%")),card("MATCH RUN SD",if(is.finite(variability))round(variability,1) else "—")))})
  output$player_seasons<-renderPlotly({x<-px(); if(!nrow(x))return(NULL); s<-sort(unique(x$season[!is.na(x$season)])); a<-do.call(rbind,lapply(s,function(y){z<-x[x$season==y,,drop=FALSE]; data.frame(season=y,runs=sum(z$runs_batter))})); plotly::plot_ly(a,x=~season,y=~runs,type="scatter",mode="lines+markers",line=list(color="#46e6a5")) |> plotly::layout(title="Runs by season",paper_bgcolor="transparent",plot_bgcolor="transparent",font=list(color="#cbd5e1"))})
  output$player_phases<-renderPlotly({a<-phase_summary(px(),input$player); if(!nrow(a))return(NULL); plotly::plot_ly(a,x=~phase,y=~strike_rate,type="bar",marker=list(color="#52c7e8"),text=~paste("Balls faced:",balls),hoverinfo="text+y") |> plotly::layout(title="Phase strike rate",paper_bgcolor="transparent",plot_bgcolor="transparent",font=list(color="#cbd5e1"),yaxis=list(title="Strike rate"))})
  output$player_bowling<-renderDT({a<-player_bowling(player_bowling_rows()); if(nrow(a)){names(a)<-c("Player","Balls","Overs bowled","Runs conceded","Wickets","Economy","Bowling avg","Bowling SR","Matches"); a$`Overs bowled`<-round(a$`Overs bowled`,1); a$Economy<-round(a$Economy,2); a$`Bowling avg`<-round(a$`Bowling avg`,2); a$`Bowling SR`<-round(a$`Bowling SR`,2)}; datatable(a,options=list(dom="tip",scrollX=TRUE,autoWidth=FALSE),rownames=FALSE)})
  impact_base<-reactive({x<-filtered(); if(is.null(x))return(NULL); if(!is.null(input$player_season)&&input$player_season!="All seasons")x<-x[x$season==as.numeric(input$player_season),,drop=FALSE]; if(!is.null(input$player_opposition)&&input$player_opposition!="All teams")x<-x[x$opposition==input$player_opposition,,drop=FALSE]; if(!is.null(input$player_venue)&&input$player_venue!="All venues")x<-x[x$venue==input$player_venue,,drop=FALSE]; list(batting=player_batting(x,30),bowling=player_bowling(x))})
  output$impact_weights<-renderText({paste0("Current blend: batting ",round(input$bat_weight*100),"% · bowling ",round(input$bowl_weight*100),"%. Scores are relative to eligible players in the filtered data.")})
  output$impact_note<-renderUI({base<-impact_base(); if(is.null(base))return(NULL); if(!input$bat_weight&&!input$bowl_weight)return(p("Set at least one weight above zero to calculate a score.")); a<-impact_score(base$batting,base$bowling,input$bat_weight,input$bowl_weight); row<-a[a$player==input$player,,drop=FALSE]; if(!nrow(row)||!is.finite(row$impact[1]))return(p("Insufficient peer or role sample for a reliable score. Batting needs at least 30 balls and two eligible players; bowling needs at least 12 legal balls and two eligible players.")); p("Impact score = the weighted average of role-specific standardized performance, reduced for small opportunities. Batting uses average and strike-rate efficiency; bowling uses economy and wicket rate. Missing role data is excluded and remaining weights are renormalized. This is a comparison within the selected filters, not an official rating.")})
  output$impact_table<-renderDT({base<-impact_base(); validate(need(!is.null(base),"No records match these filters.")); a<-impact_score(base$batting,base$bowling,input$bat_weight,input$bowl_weight); a<-a[a$player==input$player,,drop=FALSE]; if(!nrow(a))a<-data.frame(Note="No eligible batting or bowling sample for this player under the selected filters."); if("impact"%in%names(a)){a$impact<-round(a$impact,3); a$batting_contribution<-round(a$batting_contribution,3); a$bowling_contribution<-round(a$bowling_contribution,3); names(a)<-c("Player","Role","Impact score","Batting component","Bowling component","Batting balls","Batting matches","Bowling balls","Bowling matches")}; datatable(a,options=list(pageLength=5,scrollX=TRUE,autoWidth=FALSE),rownames=FALSE)})
  output$player_matches<-renderDT({datatable(player_match_batting(px(),input$player),options=list(pageLength=12,order=list(list(2,"desc"))),rownames=FALSE)})

  output$teams<-renderUI({if(is.null(d))return(empty_panel()); tagList(page_head("TEAM INTELLIGENCE / 03","Franchise performance","Results use match-level outcomes; win rate denominator excludes ties and no-results."),div(class="filters",selectInput("team_pick","Team",choices=sort(unique(na.omit(d$team))))),div(class="grid two",div(class="panel",plotlyOutput("team_seasons",height="300px")),div(class="panel",plotlyOutput("team_phase",height="300px"))),div(class="grid two",div(class="panel",h3("Toss decision patterns"),DTOutput("toss_table")),div(class="panel",h3("Team record"),DTOutput("team_table"))))})
  output$team_table<-renderDT({datatable(team_records(filtered()),options=list(pageLength=20,scrollX=TRUE,autoWidth=FALSE),rownames=FALSE)})
  output$team_seasons<-renderPlotly({a<-team_season_records(filtered()); a<-a[a$team==input$team_pick,,drop=FALSE]; if(!nrow(a))return(NULL); plotly::plot_ly(a,x=~season,y=~win_pct,type="scatter",mode="lines+markers",line=list(color="#46e6a5"),text=~paste("Wins:",wins,"Played:",played),hoverinfo="text+y") |> plotly::layout(title="Selected team win rate by season",paper_bgcolor="transparent",plot_bgcolor="transparent",font=list(color="#cbd5e1"),yaxis=list(title="Win %"),margin=list(t=55,b=55,l=55,r=20))})
  output$team_phase<-renderPlotly({x<-filtered(); x<-x[x$team==input$team_pick,,drop=FALSE]; a<-phase_summary(x); if(!nrow(a))return(NULL); plotly::plot_ly(a,x=~phase,y=~runs,type="bar",marker=list(color="#52c7e8")) |> plotly::layout(title="Runs by batting phase",paper_bgcolor="transparent",plot_bgcolor="transparent",font=list(color="#cbd5e1"),xaxis=list(title="Batting phase"),yaxis=list(title="Runs"),margin=list(t=55,b=55,l=55,r=20))})
  output$toss_table<-renderDT({datatable(match_condition_summary(filtered(),"toss_decision"),options=list(dom="tip",scrollX=TRUE,autoWidth=FALSE),rownames=FALSE)})

  output$venues<-renderUI({if(is.null(d))return(empty_panel()); tagList(page_head("VENUE INTELLIGENCE / 04","Ground conditions in the scorebook","Observed scoring patterns are proxies, not physical pitch measurements. Match counts are included."),div(class="panel",DTOutput("venues_all")),div(class="panel",plotlyOutput("venue_plot",height="350px")))})
  venue_stats<-reactive({x<-filtered(); v<-venue_summary(x); cnd<-match_condition_summary(x,"venue"); if(!nrow(v))return(data.frame()); merge(v,cnd[,c("category","batting_first_wins","chasing_wins","batting_first_pct","chasing_pct","toss_winner_wins")],by.x="venue",by.y="category",all.x=TRUE,sort=FALSE)})
  output$venues_all<-renderDT({v<-venue_stats(); datatable(v[order(-v$matches),],options=list(pageLength=20,scrollX=TRUE,autoWidth=FALSE),rownames=FALSE)})
  output$venue_plot<-renderPlotly({a<-venue_stats(); a<-a[a$matches>=3,]; if(!nrow(a))return(NULL); plotly::plot_ly(a,x=~reorder(venue,first_avg),y=~first_avg,type="bar",marker=list(color="#46e6a5"),text=~paste("Matches:",matches),hoverinfo="text+y") |> plotly::layout(title="First-innings average · venues with at least 3 matches",paper_bgcolor="transparent",plot_bgcolor="transparent",font=list(color="#cbd5e1"),xaxis=list(title="Venue",tickangle=-40),yaxis=list(title="Average score"),margin=list(t=55,b=120,l=55,r=20))})

  output$h2h<-renderUI({if(is.null(d))return(empty_panel()); players<-sort(unique(na.omit(d$player))); teams<-sort(unique(na.omit(d$team))); venues<-sort(unique(na.omit(d$venue))); tagList(page_head("MATCHUP LAB / 05","Head-to-head","Compare player output at a selected venue or inspect historical franchise matchups."),div(class="filters",selectInput("h2h_a","Player A",players),selectInput("h2h_b","Player B",players,selected=players[min(2,length(players))]),selectInput("h2h_venue","Player venue",c("All venues",venues))),div(class="panel",h3("Player comparison"),p("Batting and bowling profiles are compared separately using the active global filters and selected venue. Low samples are labeled; missing role statistics are left blank."),DTOutput("h2h_table")),div(class="panel",plotlyOutput("h2h_plot",height="300px")),div(class="filters",selectInput("h2h_team_a","Team A",teams),selectInput("h2h_team_b","Team B",teams,selected=teams[min(2,length(teams))])),div(class="panel",h3("Franchise matchup"),DTOutput("team_h2h_table")))})
  h2hdata<-reactive({x<-filtered();if(!is.null(input$h2h_venue)&&input$h2h_venue!="All venues")x<-x[x$venue==input$h2h_venue,,drop=FALSE]; player_batting(x[x$player%in%c(input$h2h_a,input$h2h_b),,drop=FALSE])})
  output$h2h_table<-renderDT({a<-h2h_player_profiles({x<-filtered();if(!is.null(input$h2h_venue)&&input$h2h_venue!="All venues")x<-x[x$venue==input$h2h_venue,,drop=FALSE];x},input$h2h_a,input$h2h_b); if(nrow(a)){names(a)<-c("Profile","Statistic",paste(input$h2h_a,"(A)"),paste(input$h2h_b,"(B)"),paste(input$h2h_a,"sample"),paste(input$h2h_b,"sample"),"Sample status"); numeric_cols<-vapply(a,is.numeric,logical(1)); a[numeric_cols]<-lapply(a[numeric_cols],round,2)}; datatable(a,options=list(dom="tip",scrollX=TRUE,autoWidth=FALSE),rownames=FALSE)})
  output$h2h_plot<-renderPlotly({a<-h2hdata(); if(!all(c(input$h2h_a,input$h2h_b)%in%a$player))return(NULL); plotly::plot_ly(a,x=~player,y=~strike_rate,type="bar",color=~player,colors=c("#46e6a5","#52c7e8"),text=~paste("Balls:",balls,"Matches:",matches),hoverinfo="text+y") |> plotly::layout(title="Strike rate · batting profiles",paper_bgcolor="transparent",plot_bgcolor="transparent",font=list(color="#cbd5e1"),xaxis=list(title="Player"),yaxis=list(title="Strike rate"),margin=list(t=55,b=60,l=55,r=20))})
  output$team_h2h_table<-renderDT({datatable(team_head_to_head(filtered(),input$h2h_team_a,input$h2h_team_b),options=list(dom="tip",scrollX=TRUE,autoWidth=FALSE),rownames=FALSE)})

  model_result<-shiny::reactiveVal(if(is.null(d)) list(available=FALSE,message="Dataset required.") else NULL)
  get_chase_model<-function(data) {
    path<-file.path("models","chase_model.rds"); data_cache<-file.path("data","processed","deliveries.rds")
    source_time<-if(file.exists(data_cache)) as.numeric(file.info(data_cache)$mtime) else NA_real_
    if(file.exists(path)) {saved<-tryCatch(readRDS(path),error=function(e)NULL); if(!is.null(saved)&&identical(saved$source_time,source_time)) return(saved$result)}
    result<-evaluate_chase_model(data); dir.create(dirname(path),recursive=TRUE,showWarnings=FALSE)
    saveRDS(list(source_time=source_time,result=result),path); result
  }
  shiny::observeEvent(input$nav,{
    if(!is.null(d)&&identical(input$nav,navs[6])&&is.null(model_result())) {
      shiny::withProgress(message="Training and evaluating the chase model",value=0,{
        shiny::incProgress(.15,detail="Building match-grouped chase snapshots")
        m<-get_chase_model(d)
        shiny::incProgress(.85,detail="Checking chronological holdout")
        model_result(m)
      })
    }
  },ignoreInit=TRUE)
  output$predictions<-renderUI({if(is.null(d))return(empty_panel()); mr<-model_result(); evaluation<-if(is.null(mr)) p("The chase model trains on first use. This may take a short while for the full dataset.") else if(mr$available) tagList(p("Chronological holdout ending at ",as.character(mr$cutoff)),p("Test accuracy: ",round(100*mr$accuracy,1),"% · Brier score: ",round(mr$brier,3)," · Held-out matches: ",mr$test_matches)) else p(mr$message); tagList(page_head("PREDICTIVE ANALYTICS / 06","Match situation model","An in-match chase model uses current runs, wickets and balls remaining. Evaluation holds out later matches chronologically."),div(class="panel",evaluation),div(class="filters",numericInput("score","Chasing score",120,min=0),numericInput("target","Target",180,min=1),numericInput("lost","Wickets lost",3,min=0,max=10),numericInput("balls","Legal balls used",72,min=0,max=120)),uiOutput("prediction_result"),div(class="panel",h3("Player role clusters"),DTOutput("clusters")))})
  output$prediction_result<-renderUI({mr<-model_result(); if(is.null(mr)||!isTRUE(mr$available))return(NULL); p<-predict_chase(mr$model,input$score,input$target,input$lost,input$balls); div(class="prediction",span("Chasing team win probability"),strong(paste0(round(100*p,1),"%")),small("Model estimate; historical conditions may differ."))})
  output$clusters<-renderDT({a<-player_batting(d,50); if(nrow(a)<4)return(datatable(data.frame(Note="At least four players with 50+ valid balls are required."))); m<-scale(cbind(a$strike_rate,a$average,a$boundary_pct)); set.seed(42); k<-min(4,nrow(a)-1); cl<-tryCatch(stats::kmeans(m,centers=k,nstart=10)$cluster,error=function(e)rep(NA,nrow(a))); datatable(data.frame(player=a$player,runs=a$runs,strike_rate=round(a$strike_rate,1),cluster=cl),options=list(pageLength=12),rownames=FALSE)})

  text_columns<-if(is.null(d))character() else names(d)[vapply(d,function(x)is.character(x)||is.factor(x),logical(1))]
  category_columns<-if(is.null(d))character() else names(d)[vapply(d,function(x)(is.character(x)||is.factor(x))&&length(unique(stats::na.omit(x)))<=1000,logical(1))]
  numeric_columns<-if(is.null(d))character() else names(d)[vapply(d,is.numeric,logical(1))]
  date_values<-if(is.null(d)||!inherits(d$date,"Date"))as.Date(character()) else d$date[!is.na(d$date)]
  text_columns<-if(is.null(d))character() else names(d)[vapply(d,function(x)is.character(x)||is.factor(x),logical(1))]
  category_columns<-if(is.null(d))character() else names(d)[vapply(d,function(x)(is.character(x)||is.factor(x))&&length(unique(stats::na.omit(x)))<=1000,logical(1))]
  numeric_columns<-if(is.null(d))character() else names(d)[vapply(d,is.numeric,logical(1))]
  date_values<-if(is.null(d)||!inherits(d$date,"Date"))as.Date(character()) else d$date[!is.na(d$date)]
  output$explorer<-renderUI({if(is.null(d))return(empty_panel()); tagList(page_head("DATA EXPLORER / 07","Inspect the evidence","Filter the full cleaned dataset, inspect validation and missingness, then export every matching row."),div(class="filters explorer-search",textInput("explore_search","Search all text fields",placeholder="Search players, teams, venues, IDs…"),actionButton("explore_reset","Reset all filters")),tags$details(class="filter-details",tags$summary("Column filters"),div(class="filter-builder",lapply(1:3,function(i)div(class="filter-slot",selectInput(paste0("explore_cat_col_",i),paste("Category filter",i),choices=c("None"="",category_columns)),uiOutput(paste0("explore_cat_values_",i)))),lapply(1:2,function(i)div(class="filter-slot",selectInput(paste0("explore_text_col_",i),paste("Text column",i),choices=c("None"="",text_columns)),textInput(paste0("explore_text_query_",i),"Contains text",placeholder="Optional"))),lapply(1:3,function(i)div(class="filter-slot",selectInput(paste0("explore_num_col_",i),paste("Numeric range",i),choices=c("None"="",numeric_columns)),numericInput(paste0("explore_num_min_",i),"Minimum",value=NA),numericInput(paste0("explore_num_max_",i),"Maximum",value=NA))),if(length(date_values))tagList(checkboxInput("explore_use_date","Filter by date",value=FALSE),dateRangeInput("explore_date","Date range",start=min(date_values),end=max(date_values),min=min(date_values),max=max(date_values))))),uiOutput("explore_count"),div(class="panel",h3("Raw source preview · first 30 rows"),DTOutput("raw_table")),p(paste(nrow(d),"cleaned delivery rows ·",length(names(d)),"canonical fields")),div(class="panel",h3("Validation summary"),DTOutput("validation_table")),div(class="grid two",div(class="panel",h3("Field types"),DTOutput("schema_table")),div(class="panel",h3("Missing values"),DTOutput("missing_table"))),div(class="panel",h3("Filtered deliveries · preview capped at 50,000 rows"),DTOutput("data_table")),downloadButton("download_data","Download all filtered rows",class="btn-primary"))})
  for(i in 1:3)local({idx<-i; output[[paste0("explore_cat_values_",idx)]]<-renderUI({col<-input[[paste0("explore_cat_col_",idx)]]; if(is.null(col)||!nzchar(col)||!col%in%names(d))return(NULL); vals<-sort(unique(stats::na.omit(as.character(d[[col]])))); selectizeInput(paste0("explore_cat_values_",idx),"Values (leave empty for all)",choices=vals,multiple=TRUE,options=list(placeholder="Choose one or more values"))})})
  ex<-reactive({if(is.null(d))return(NULL); categories<-lapply(1:3,function(i)list(column=input[[paste0("explore_cat_col_",i)]],values=input[[paste0("explore_cat_values_",i)]])); text_filters<-lapply(1:2,function(i)list(column=input[[paste0("explore_text_col_",i)]],query=input[[paste0("explore_text_query_",i)]])); numeric_filters<-lapply(1:3,function(i)list(column=input[[paste0("explore_num_col_",i)]],min=input[[paste0("explore_num_min_",i)]],max=input[[paste0("explore_num_max_",i)]])); filter_explorer_data(d,input$explore_search,text_filters,categories,numeric_filters,if(isTRUE(input$explore_use_date))input$explore_date else NULL)})
  output$explore_count<-renderUI({x<-ex(); n<-nrow(x); div(class="filter-count",if(n==0)"No rows match these filters." else paste(format(n,big.mark=","),"matching rows. Showing the first",format(min(n,50000),big.mark=","),"in the preview; the CSV download includes all matches."))})
  observeEvent(input$explore_reset,{updateTextInput(session,"explore_search",value="");for(i in 1:3){updateSelectInput(session,paste0("explore_cat_col_",i),selected="");updateSelectizeInput(session,paste0("explore_cat_values_",i),selected=character(0));updateSelectInput(session,paste0("explore_num_col_",i),selected="");updateNumericInput(session,paste0("explore_num_min_",i),value=NA);updateNumericInput(session,paste0("explore_num_max_",i),value=NA)};for(i in 1:2){updateSelectInput(session,paste0("explore_text_col_",i),selected="");updateTextInput(session,paste0("explore_text_query_",i),value="")};if(length(date_values)){updateCheckboxInput(session,"explore_use_date",value=FALSE);updateDateRangeInput(session,"explore_date",start=min(date_values),end=max(date_values))}},ignoreInit=TRUE)
  output$schema_table<-renderDT({datatable(data.frame(field=names(d),type=vapply(d,function(x)class(x)[1],"")),options=list(pageLength=12),rownames=FALSE)})
  output$raw_table<-renderDT({files<-list.files("data/raw",pattern="\\.csv$",full.names=TRUE,ignore.case=TRUE); if(!length(files))return(datatable(data.frame(Note="No source CSV found."))); raw<-utils::read.csv(files[1],nrows=30,stringsAsFactors=FALSE,check.names=FALSE); datatable(raw,options=list(pageLength=10,scrollX=TRUE),rownames=FALSE)})
  output$validation_table<-renderDT({datatable(data.frame(check=c("Source columns","Duplicate source rows","Rows missing match/team/player/innings","Normalized rows"),value=c(length(attr(d,"source_columns")),attr(d,"duplicate_rows")%||%NA,attr(d,"missing_core_rows")%||%NA,nrow(d))),options=list(dom="t"),rownames=FALSE)})
  output$missing_table<-renderDT({datatable(data.frame(field=names(d),missing=vapply(d,function(x)sum(is.na(x)),0L)),options=list(pageLength=12),rownames=FALSE)})
  output$data_table<-renderDT({x<-ex(); if(!nrow(x))return(datatable(data.frame(Note="No rows match these filters."),options=list(dom="t"),rownames=FALSE)); datatable(utils::head(x,50000),options=list(pageLength=15,scrollX=TRUE,autoWidth=FALSE,searching=FALSE),rownames=FALSE)})
  output$download_data<-downloadHandler(filename=function()"criclens_filtered_deliveries.csv",content=function(file)write.csv(ex(),file,row.names=FALSE,na=""))

  output$ask<-renderUI({if(is.null(d))return(empty_panel()); tagList(page_head("ASK CRICLENS / 08","Ask the analytics engine","R selects and computes an allowlisted analysis. NVIDIA NIM can summarize those results when configured."),div(class="panel",textAreaInput("question","Your question",placeholder="Which players perform best in death overs?",width="100%",rows=3),actionButton("ask_button","Calculate answer",class="btn-primary"),uiOutput("ai_answer")),div(class="examples",span("Try:"),actionLink("ex1","Death-over performers"),actionLink("ex2","Highest scoring venues"),actionLink("ex3","Team win records")))})
  observeEvent(input$ex1,{updateTextAreaInput(session,"question",value="Which players perform best in death overs?")});observeEvent(input$ex2,{updateTextAreaInput(session,"question",value="Which venues have the highest average first-innings scores?")});observeEvent(input$ex3,{updateTextAreaInput(session,"question",value="How successful are teams when chasing?")})
  answer<-eventReactive(input$ask_button,{req(nzchar(input$question)); req<-route_question(input$question); validate(need(validate_ai_request(req),"Unsupported analytical request.")); result<-execute_ai_request(req,d); list(result=result,explanation=explain_with_nim(input$question,result))})
  output$ai_answer<-renderUI({a<-answer();req<-a$result; tagList(h3(req$title),p(a$explanation),p(req$note),DTOutput("ai_table"))})
  output$ai_table<-renderDT({req<-answer()$result;datatable(req$data,options=list(pageLength=10),rownames=FALSE)})
}
shinyApp(ui,server)
